from openpyxl import load_workbook
from openpyxl.styles import Font

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Set font to '等线' for the entire sheet
font = Font(name="等线")

# Apply font to all cells in the sheet
for row in ws.iter_rows():
    for cell in row:
        cell.font = font

# Define the range to process (N7:O23)
start_row, end_row = 7, 23
start_col_n, start_col_o = 13, 14  # Columns N and O

# Process each row in the range
for row in range(start_row, end_row + 1):
    cell_n = ws.cell(row, start_col_n)
    cell_o = ws.cell(row, start_col_o)

    # Check if the value in column N is numeric
    if cell_n.value is not None and isinstance(cell_n.value, (int, float)):
        if cell_n.value > 40:
            # Calculate overtime
            overtime = cell_n.value - 40
            cell_n.value = 40
            cell_o.value = overtime
        else:
            # No overtime, clear column O
            cell_o.value = None
    else:
        # Non-numeric value, clear column O
        cell_o.value = None

# Apply number formatting
for row in range(start_row, end_row + 1):
    cell_n = ws.cell(row, start_col_n)
    cell_o = ws.cell(row, start_col_o)

    # Apply #,##0.## formatting for non-integer values, General for integers
    if cell_n.value is not None:
        if isinstance(cell_n.value, float):
            if cell_n.value.is_integer():
                cell_n.number_format = "General"
            else:
                cell_n.number_format = "#,##0.##"
        else:
            cell_n.number_format = "General"

    if cell_o.value is not None:
        if isinstance(cell_o.value, float):
            if cell_o.value.is_integer():
                cell_o.number_format = "General"
            else:
                cell_o.number_format = "#,##0.##"
        else:
            cell_o.number_format = "General"

# Save the workbook
wb.save("output.xlsx")
