from openpyxl import load_workbook
from datetime import datetime

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Define the ranges
month_names = [ws[f"B{i}"].value for i in range(3, 15)]  # B3:B14
month_end_dates = [ws[f"B{i}"].value for i in range(17, 25)]  # B17:B24
data_rows = [ws[f"A{i}:G{i}"].values for i in range(3, 25)]  # A3:G24

# Map month names to their corresponding month end dates
month_to_date = {}
for month, date in zip(month_names, month_end_dates):
    month_to_date[month] = date

# Extract the month from the date (e.g., "Jan", "Feb", etc.)
def get_month_name(date):
    return datetime.strftime(date, "%b")

# Map each data row to its corresponding month
data_by_month = {}
for row in data_rows:
    date_cell = row[1]  # B column
    if date_cell:
        month_name = get_month_name(date_cell)
        if month_name not in data_by_month:
            data_by_month[month_name] = []
        data_by_month[month_name].append(row)

# Calculate totals for each month
totals_by_month = {}
for month, rows in data_by_month.items():
    totals = [0] * 5  # DK, INSP, CONT, APPR, CLS
    for row in rows:
        for i in range(2, 7):  # Columns C to G (indices 2 to 6)
            value = row[i]
            if value is not None:
                totals[i - 2] += value
    totals_by_month[month] = totals

# Write the totals to the answer range C3:G14
for row_idx, month in enumerate(month_names, start=3):
    if month in totals_by_month:
        totals = totals_by_month[month]
        for col_idx, value in enumerate(totals, start=2):
            ws.cell(row=row_idx, column=col_idx, value=value if value != 0 else None)

# Save the workbook
wb.save("output.xlsx")
